sp_widget.client_script:
function($scope, $location, $http, spUtil, $window) {
    var c = this;
    c.view = $location.search().id || 'admin_dashboard';
    c.claimId = $location.search().sys_id || null;

    c.navItems = [
        { id: 'admin_dashboard', label: 'Admin Dashboard', icon: 'fa-home' },
        { id: 'admin_claims', label: 'Claims Management', icon: 'fa-list-alt' },
        { id: 'admin_documents', label: 'Document Verification', icon: 'fa-file-text' },
        { id: 'admin_fraud', label: 'Fraud Assessment', icon: 'fa-shield' },
        { id: 'admin_settlement', label: 'Settlement', icon: 'fa-balance-scale' },
        { id: 'admin_approvals', label: 'Approvals', icon: 'fa-check-square-o' },
        { id: 'admin_payments', label: 'Payments', icon: 'fa-money' },
        { id: 'admin_customers', label: 'Customers', icon: 'fa-users' },
        { id: 'admin_reports', label: 'Reports & Analytics', icon: 'fa-bar-chart' },
        { id: 'admin_notifications', label: 'Notifications', icon: 'fa-bell' },
        { id: 'admin_ai', label: 'AI / Virtual Agent', icon: 'fa-comments' },
        { id: 'admin_settings', label: 'Settings', icon: 'fa-cog' }
    ];

    c.navigate = function(id, sys_id) {
        var params = { id: id };
        if (sys_id) params.sys_id = sys_id;
        $location.search(params);
    };

    c.logout = function() {
        $window.location.href = '/logout.do';
    };

    c.editing = {};
    c.editField = function(recordId, field) {
        if (!c.editing[recordId]) c.editing[recordId] = {};
        c.editing[recordId][field] = true;
    };

    c.saveField = function(recordId, table, field, value) {
        c.server.get({
            action: 'update_field',
            recordId: recordId,
            table: table,
            field: field,
            value: value
        }).then(function(r) {
            c.editing[recordId][field] = false;
            spUtil.addInfoMessage("Updated successfully.");
            c.server.update();
        });
    };

    c.cancelEdit = function(recordId, field) {
        c.editing[recordId][field] = false;
    };

    c.approveDoc = function(docId) {
        c.saveField(docId, 'x_snc_insurance_0_claim_document', 'document_validation_status', 'Approved');
    };

    c.rejectDoc = function(docId) {
        var reason = prompt("Enter rejection reason:");
        if (reason) {
            c.server.get({
                action: 'reject_doc',
                docId: docId,
                reason: reason
            }).then(function() {
                spUtil.addInfoMessage("Document rejected.");
                c.server.update();
            });
        }
    };
}

sp_widget.css:
.admin-portal { display: flex; min-height: 100vh; background: #f4f7f9; font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif; }
.sidebar { width: 260px; background: #12305b; color: #fff; padding: 20px 0; display: flex; flex-direction: column; }
.sidebar-header { padding: 0 20px 20px; text-align: center; border-bottom: 1px solid rgba(255,255,255,0.1); margin-bottom: 20px; }
.nav-item { padding: 15px 20px; color: #a5b4c6; cursor: pointer; transition: 0.2s; text-decoration: none; display: flex; align-items: center; gap: 10px; }
.nav-item:hover, .nav-item.active { background: rgba(255,255,255,0.1); color: #fff; border-left: 4px solid #1769d1; }
.main-content { flex: 1; padding: 30px; overflow-y: auto; }
.header-bar { display: flex; justify-content: space-between; margin-bottom: 30px; align-items: center; }
.card { background: #fff; border-radius: 12px; padding: 20px; box-shadow: 0 4px 15px rgba(0,0,0,0.05); margin-bottom: 20px; border: 1px solid #e5ebf3; }
.stat-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 20px; margin-bottom: 30px; }
.stat-card { background: #fff; padding: 20px; border-radius: 12px; box-shadow: 0 4px 15px rgba(0,0,0,0.05); border-left: 4px solid #1769d1; }
.stat-value { font-size: 28px; font-weight: 700; color: #12305b; margin: 10px 0; }
.table { width: 100%; border-collapse: collapse; }
.table th { text-align: left; padding: 12px; border-bottom: 2px solid #e5ebf3; color: #7c8da2; }
.table td { padding: 12px; border-bottom: 1px solid #e5ebf3; color: #12305b; }
.btn { padding: 8px 15px; border-radius: 6px; cursor: pointer; border: none; font-weight: 600; }
.btn-primary { background: #1769d1; color: #fff; }
.btn-outline { background: transparent; border: 1px solid #1769d1; color: #1769d1; }
.btn-small { padding: 4px 8px; font-size: 12px; }
.badge { padding: 4px 8px; border-radius: 12px; font-size: 12px; font-weight: 600; }
.badge-pending { background: #fef3c7; color: #92400e; }
.badge-approved { background: #dcfce7; color: #166534; }
.badge-rejected { background: #fee2e2; color: #991b1b; }
.edit-inline { display: flex; gap: 10px; align-items: center; }

sp_widget.script:
(function() {
    data.is_admin = gs.hasRole('admin') || gs.hasRole('x_snc_insurance_0.claim admin');
    if (!data.is_admin) return;

    if (input && input.action == 'update_field') {
        var gr = new GlideRecordSecure(input.table);
        if (gr.get(input.recordId)) {
            gr.setValue(input.field, input.value);
            gr.update();
        }
        return;
    }

    if (input && input.action == 'reject_doc') {
        var doc = new GlideRecordSecure('x_snc_insurance_0_claim_document');
        if (doc.get(input.docId)) {
            doc.setValue('document_validation_status', 'Rejected');
            doc.setValue('rejection_reason', input.reason);
            doc.update();
        }
        return;
    }

    data.stats = { total: 0, pending: 0, approved: 0, rejected: 0 };
    var claimCount = new GlideRecordSecure('x_snc_insurance_0_claim');
    claimCount.query();
    while (claimCount.next()) {
        data.stats.total++;
        var st = claimCount.getValue('status');
        if (st == 'Pending') data.stats.pending++;
        if (st == 'Approved') data.stats.approved++;
        if (st == 'Rejected') data.stats.rejected++;
    }

    data.claims = [];
    var cl = new GlideRecordSecure('x_snc_insurance_0_claim');
    cl.orderByDesc('sys_created_on');
    cl.query();
    while (cl.next()) {
        data.claims.push({
            sys_id: cl.getUniqueValue(),
            number: cl.getValue('claim_number') || '',
            customer: cl.getDisplayValue('policyholder') || '',
            type: cl.getValue('claim_type') || '',
            amount: cl.getDisplayValue('claim_amount') || '',
            status: cl.getValue('status') || '',
            fraud_risk: cl.getValue('fraud_risk') || '',
            fraud_score: cl.getValue('fraud_score') || '',
            adjuster_decision: cl.getValue('adjuster_decision') || '',
            payment_status: cl.getValue('payment_status') || '',
            final_payout: cl.getDisplayValue('final_payout') || ''
        });
    }

    data.documents = [];
    var docs = new GlideRecordSecure('x_snc_insurance_0_claim_document');
    docs.orderByDesc('sys_created_on');
    docs.query();
    while (docs.next()) {
        data.documents.push({
            sys_id: docs.getUniqueValue(),
            name: docs.getValue('document_name') || '',
            claim_number: docs.getDisplayValue('claim') || '',
            type: docs.getValue('document_type') || '',
            status: docs.getValue('document_validation_status') || ''
        });
    }
})();
